package android.net.nsd;import android.net.Network;import java.util.*;import java.util.concurrent.Executor;
public class NsdManager{public static final int PROTOCOL_DNS_SD=1,FAILURE_ALREADY_ACTIVE=3;public DiscoveryListener listener;public Network selected;public int stops,unregistered,legacyCalls;public final LinkedHashMap<String,ServiceInfoCallback> callbacks=new LinkedHashMap<>();public final LinkedHashMap<String,ResolveListener> legacy=new LinkedHashMap<>();public interface DiscoveryListener{void onDiscoveryStarted(String t);void onDiscoveryStopped(String t);void onStartDiscoveryFailed(String t,int code);void onStopDiscoveryFailed(String t,int code);void onServiceFound(NsdServiceInfo s);void onServiceLost(NsdServiceInfo s);}public interface ResolveListener{void onResolveFailed(NsdServiceInfo s,int error);void onServiceResolved(NsdServiceInfo s);}public interface ServiceInfoCallback{void onServiceInfoCallbackRegistrationFailed(int code);void onServiceUpdated(NsdServiceInfo s);void onServiceLost();void onServiceInfoCallbackUnregistered();}public void discoverServices(String t,int p,DiscoveryListener l){listener=l;}public void discoverServices(String t,int p,Network n,Executor e,DiscoveryListener l){selected=n;listener=l;}public void stopServiceDiscovery(DiscoveryListener l){stops++;}public void registerServiceInfoCallback(NsdServiceInfo info,Executor e,ServiceInfoCallback c){callbacks.put(info.name,c);}public void unregisterServiceInfoCallback(ServiceInfoCallback c){unregistered++;}public void resolveService(NsdServiceInfo s,ResolveListener l){legacyCalls++;legacy.put(s.name,l);}public void stopServiceResolution(ResolveListener listener){}}

